'use strict';
const $=id=>document.getElementById(id);
const state={engine:false,token:'',video:null,cues:[],framing:'crop',style:'clean',busy:false,objectURL:null,captionRange:null};
const preview=$('preview');
function status(message,type=''){ $('status-text').textContent=message;$('status').className='status '+type; }
function setup(){ $('setup').showModal(); }
$('help').onclick=setup; document.querySelectorAll('.setup').forEach(b=>b.onclick=setup);$('close-setup').onclick=()=>$('setup').close();
async function connect(){
  if(!['127.0.0.1','localhost'].includes(location.hostname)){hosted();return;}
  try{const r=await fetch('/api/session');if(!r.ok)throw Error(); const s=await r.json();state.engine=s.engine;state.token=s.token;$('connection').textContent='● Engine connected';$('connection').classList.add('connected');status('Engine connected. Paste a link or choose your original video.');}
  catch{hosted();}
}
function hosted(){ $('connection').textContent='Web preview';$('hosted-note').hidden=false;status('Preview a local video here, or start the desktop engine for captions and exports.'); }
function requireEngine(){if(!state.engine){setup();throw Error('Start the desktop engine, then use its local editor.');}}
async function api(path,data){const r=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json','X-ClipForge-Token':state.token},body:JSON.stringify(data)});const res=await r.json();if(!r.ok)throw Error(res.error||'Request failed');return res;}
async function job(id){while(true){const r=await fetch('/api/jobs/'+id);if(!r.ok)throw Error('The engine lost this job. Re-import your video.');const j=await r.json();status(j.message,j.state==='error'?'error':'working');if(j.state==='done')return j.result;if(j.state==='error')throw Error(j.message);await new Promise(r=>setTimeout(r,1100));}}
function setBusy(b){state.busy=b;['import','transcribe','export','file','add-caption','start','end','position','crop','fit','model','resolution','quality'].forEach(id=>$(id).disabled=b);document.querySelectorAll('.quick button,.style-card,.cue input,.cue textarea,.cue button').forEach(el=>el.disabled=b);}
async function action(fn){if(state.busy)return;setBusy(true);try{await fn();}catch(e){status(e.message,'error');}finally{setBusy(false);}}
function time(n){return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(Math.floor(n%60)).padStart(2,'0')}`;}
function range(){const start=Number($('start').value),end=Number($('end').value);if(!state.video)throw Error('Import or choose a video first.');if(!Number.isFinite(start)||!Number.isFinite(end)||start<0||end-start<.1||end>state.video.duration+.05||end-start>180)throw Error('Choose valid start and end times, with a maximum length of 180 seconds.');return {start,end};}
function loadVideo(v,url){state.video=v;state.cues=[];state.captionRange=null;renderCues();$('result').hidden=true;$('video-title').textContent=v.title;$('source-meta').textContent=`${v.width} × ${v.height} · ${time(v.duration)} · ${v.fps||'original'} fps`; $('start').value=0;$('end').value=Math.min(30,v.duration).toFixed(1);$('start').max=v.duration;$('end').max=v.duration;preview.src=url;preview.style.display='block';$('empty-preview').hidden=true;updateRange();applyFrame();}
$('import').onclick=()=>action(async()=>{requireEngine();const url=$('url').value.trim();if(!url)throw Error('Paste a YouTube video link first.');status('Preparing your source…','working');const res=await api('import',{url});const v=await job(res.job);loadVideo(v,'/sources/'+v.id);status('Source ready. Choose the moment you want to share.');});
$('url').addEventListener('keydown',e=>{if(e.key==='Enter')$('import').click();});
$('file').onchange=()=>action(async()=>{const file=$('file').files[0];if(!file)return;if(file.size>2*1024**3)throw Error('Choose a video smaller than 2 GB.');status('Opening your video…','working');if(state.objectURL)URL.revokeObjectURL(state.objectURL);state.objectURL=URL.createObjectURL(file);if(state.engine){const r=await fetch('/api/upload',{method:'POST',headers:{'X-ClipForge-Token':state.token,'X-Filename':encodeURIComponent(file.name)},body:file});const res=await r.json();if(!r.ok)throw Error(res.error);res.video.title=file.name;loadVideo(res.video,state.objectURL);status('Original video ready. Select your clip times.');}else{const temp=document.createElement('video');temp.preload='metadata';await new Promise((resolve,reject)=>{temp.onloadedmetadata=resolve;temp.onerror=()=>reject(Error('Your browser cannot preview this format. Try an MP4 file.'));temp.src=state.objectURL;});loadVideo({title:file.name,width:temp.videoWidth,height:temp.videoHeight,duration:temp.duration},state.objectURL);temp.removeAttribute('src');temp.load();status('Preview ready. Use the desktop engine to generate captions and export.');}});
function updateRange(){const start=Number($('start').value),end=Number($('end').value);$('duration').textContent=Math.max(0,end-start).toFixed(1)+'s clip';$('scrub').min=start;$('scrub').max=Math.max(start,end);$('scrub').value=start;if(state.video&&preview.readyState)preview.currentTime=start;preview.pause();$('play').textContent='▶';$('play-time').textContent=`${time(start)} / ${time(end)}`;if(state.captionRange&&(state.captionRange.start!==start||state.captionRange.end!==end)){state.cues=[];state.captionRange=null;renderCues();status('Clip timing changed. Generate new captions for this selection.');}$('result').hidden=true;drawCaption();}
['start','end'].forEach(id=>$(id).onchange=updateRange);
document.querySelectorAll('[data-length]').forEach(b=>b.onclick=()=>{if(state.busy)return;const start=Number($('start').value);$('end').value=Math.min(start+Number(b.dataset.length),state.video?.duration||Infinity);document.querySelectorAll('[data-length]').forEach(x=>x.classList.toggle('selected',x===b));updateRange();});
function applyFrame(){preview.style.objectFit=state.framing==='fit'?'contain':'cover';preview.style.objectPosition=`${$('position').value}% 50%`;$('position').disabled=state.framing==='fit'||state.busy;$('position-label').textContent=Number($('position').value)===50?'Center':$('position').value+'%';$('crop').classList.toggle('selected',state.framing==='crop');$('fit').classList.toggle('selected',state.framing==='fit');}
$('crop').onclick=()=>{state.framing='crop';applyFrame();};$('fit').onclick=()=>{state.framing='fit';applyFrame();};$('position').oninput=applyFrame;
preview.onloadedmetadata=()=>{if(state.video)preview.currentTime=Number($('start').value);};preview.onerror=()=>status('This source format cannot preview in this browser. Export still works in the local editor; MP4/H.264 is best for previews.','error');
$('play').onclick=async()=>{if(!state.video)return;try{const r=range();if(preview.paused){if(preview.currentTime<r.start||preview.currentTime>=r.end-.03)preview.currentTime=r.start;await preview.play();}else preview.pause();}catch(e){status(e.message,'error');}};
preview.onplay=()=>{$('play').textContent='Ⅱ';};preview.onpause=()=>{$('play').textContent='▶';};
preview.ontimeupdate=()=>{const end=Number($('end').value);if(preview.currentTime>=end&&!preview.paused)preview.pause();$('scrub').value=preview.currentTime;$('play-time').textContent=`${time(preview.currentTime)} / ${time(end)}`;drawCaption();};
$('scrub').oninput=()=>{if(state.video){preview.currentTime=Number($('scrub').value);drawCaption();}};$('restart').onclick=()=>{if(state.video)preview.currentTime=Number($('start').value);};
function drawCaption(){const t=preview.currentTime-Number($('start').value);const c=state.cues.find(c=>t>=c.start&&t<c.end);$('caption-preview').textContent=c?.text||'';$('caption-preview').style.color=state.style==='yellow'?'#ffe600':'#fff';}
function renderCues(){const wrap=$('cues');wrap.replaceChildren();$('caption-count').textContent=state.cues.length+' caption phrases';if(!state.cues.length){const e=document.createElement('div');e.className='caption-empty';e.textContent='Your transcript will appear here. You can edit every phrase and timing.';wrap.append(e);return;}state.cues.forEach((c,i)=>{const row=document.createElement('div');row.className='cue';const times=document.createElement('div');times.className='cue-times';['start','end'].forEach((key,k)=>{if(k){const a=document.createElement('span');a.textContent='→';times.append(a);}const input=document.createElement('input');input.type='number';input.min='0';input.step='.01';input.value=Number(c[key]).toFixed(2);input.setAttribute('aria-label',`Caption ${i+1} ${key} (seconds into clip)`);input.onchange=()=>{c[key]=Number(input.value);drawCaption();};times.append(input);});const del=document.createElement('button');del.textContent='×';del.setAttribute('aria-label',`Remove caption ${i+1}`);del.onclick=()=>{state.cues.splice(i,1);renderCues();drawCaption();};times.append(del);const text=document.createElement('textarea');text.value=c.text;text.maxLength=250;text.setAttribute('aria-label',`Caption ${i+1} text`);text.oninput=()=>{c.text=text.value;drawCaption();};row.append(times,text);wrap.append(row);});}
$('add-caption').onclick=()=>{try{const r=range();const a=state.cues.length?state.cues.at(-1).end:0;if(a>=r.end-r.start)throw Error('No room after the last caption. Edit its timing first.');state.cues.push({start:a,end:Math.min(a+2,r.end-r.start),text:'Your caption'});state.captionRange=r;renderCues();$('cues').scrollTop=$('cues').scrollHeight;drawCaption();}catch(e){status(e.message,'error');}};
document.querySelectorAll('[data-style]').forEach(b=>b.onclick=()=>{state.style=b.dataset.style;document.querySelectorAll('[data-style]').forEach(x=>x.classList.toggle('selected',x===b));drawCaption();});
$('transcribe').onclick=()=>action(async()=>{requireEngine();const r=range();status('Preparing speech recognition…','working');const res=await api('caption',{video_id:state.video.id,...r,model:$('model').value});const result=await job(res.job);state.cues=result.cues;state.captionRange=r;renderCues();drawCaption();status(state.cues.length?'Captions ready. Review spelling and names before exporting.':'No speech detected. Add captions manually if needed.');});
$('export').onclick=()=>action(async()=>{requireEngine();const r=range();preview.pause();$('result').hidden=true;status('Preparing export…','working');const res=await api('export',{video_id:state.video.id,...r,cues:state.cues,framing:state.framing,position:Number($('position').value)/100,style:state.style,resolution:Number($('resolution').value),quality:$('quality').value});const out=await job(res.job);const box=$('result');box.replaceChildren();const info=document.createElement('div');info.textContent=`Ready · ${out.width} × ${out.height} · ${out.duration.toFixed(1)}s`;box.append(info);[['Download MP4',out.video_url],['Download SRT',out.srt_url]].forEach(([label,url])=>{const a=document.createElement('a');a.href=url;a.download=label.endsWith('MP4')?'clip.mp4':'captions.srt';a.textContent=label+' ↓';box.append(a);});box.hidden=false;status('Clip exported. Download your MP4 and optional subtitle file.');});
connect();
